        <Message
            at="2024-11-02T05:35:37.897895Z"
        >
            <Origin>0d9ccd42-0160-41e3-b8d6-3659b068f63c</Origin>
            <Speaker>$[[ Doug ]]( Dougs Story )</Speaker>
            <Paragraph>
                My parents divorced when I was 18 in the spring before I would go off to college. my father discovered that
                he was gay, which was something that he had been repressing for 48 years in his life. I don’t know what his
                relationship with my mother was like, but you can imagine how emotionally closed off they were. Having a
                wife and child to him was an obligation.
            </Paragraph>
            <Paragraph>
                When I went to school for my first semester, that would be the last time my father would be in my childhood
                at home. My parents had a lot going on at that time and really didn’t check in with me. I didn’t have a
                relationship with them. Could communicate mental health issues, nor have an awareness of mental health
                issues were
            </Paragraph>
            <Paragraph>
                In college, my grades were good, but my sleep wake pattern and general stability. Pattern was awful. I would
                attract Girlfriends somehow, largely out of a need for family that I was missing. But I didn’t have the
                social skills to maintain these relationships. They would last for about a year and were characterized by
                codependence and fighting to the point of screaming. I remember shouting frequently at every girlfriend I
                ever had.
            </Paragraph>
        </Message>
