        <Message
            at="2024-11-02T05:43:00.371595Z"
        >
            <Origin>3190a427-9f9e-4e99-8b1a-3a04786c551a</Origin>
            <Speaker>$[[ Doug ]]( Dougs Story )</Speaker>
            <Paragraph>
                I wanted to study mathematics but I wasn’t able to focus enough and needed a subject that was easier for me.
                I found my way into neuroscience switch might be hard for some people easier for me.. I went to the
                University of Chicago, which is an excellent school. And I had a 3.55 GPA. But again the grades masked the
                problem. I found a woman named Kasia who loved me, despite our problems. But we were fighting constantly,
                and it was incredibly unstable relationship that I have had to write an amends for I’ll get that later. I
                managed to find a job at a neuroscience lab. My work attendance could be described as chaotic at best. There
                were a whole weeks or I wouldn’t show up. I mostly needed to work at home. I found my way into more
                theoretical work so I could do it solo. But my boss accommodated this. Partly because I wasn’t paid very
                much as undergraduate researcher, but partly because I was creative enough to come up with my research
                project. I ended up with a very impressive publication. But again we have intellectual of success masking
                the problem - I couldn’t show up for the day today activities of a normal job. Yet from a résumé
                perspective, having a first author publication in nature neuroscience is pretty damn impressive. I wasn’t
                able to acknowledge how bad things were. I was up until 7 AM frequently. Or it would be more accurate to
                characterize myself is having no bedtime. Really I’ve always needed medication to have something that even
                resembles a normal sleep schedule. My sleep problems are chronic. But with a high GPA and the more
                impressive publication than possibly be inspected of an undergraduate, I got into graduate school I wanted.
                I decided to go to UCSD. It was a dumb move. I should’ve just stayed at my undergraduate school and used my
                research to get a PhD quickly. That was a critical oversight that would hurt me. I was lucky to have found a
                professor that could accommodate my bipolar, even though we didn’t know it was at the time. I would not find
                that again in graduate school
            </Paragraph>
        </Message>
