        <Message
            at="2024-11-02T06:03:25.039720Z"
        >
            <Origin>932f2e21-41ec-4e2b-af1c-ac533d94d108</Origin>
            <Speaker>$[[ Doug ]]( Dougs Story )</Speaker>
            <Paragraph>
                When I got to graduate school, there was an arrogance about me that was characteristic of the big ego that
                comes from bipolar. I would say that for most of my undergraduate years and for most of my graduate years.,
                which were ages 18 to 27, I was in some state of mania the whole time. Persistent sleep disturbance was a
                problem.
            </Paragraph>
            <Paragraph>
                I also forgot to say that my mom did catch on to their being problems with me , perhaps from when I would be
                home from school - this is college - or perhaps her noticing my sleep pattern was so off. You do come back
                home during college for at times. my mother brought me to nurse practitioner rather than a psychologist, and
                she prescribed me antidepressants, which didn’t really do anything. But I did have treatment for a time when
                I was an undergraduate. But I wasn’t ready for it yet. I didn’t ascribe to any sort of label, and the
                unstable relationships, and crazy sleep patterns were just part of who I was
            </Paragraph>
            <Paragraph>
                Back to graduate school. Again, I did fine in my classes. But graduate school is about fitting into a
                community. we had to do a rotation where you work with three professors to see if you like the labs they’re
                in. My memory is incredibly hazy from this whole time. I couldn’t even tell you the name of the first
                professor I worked for, but I do know that we failed to create a research project. I didn’t help him in
                anyway, nor did I produce anything useful. But it was a rotation there was no grade it was for my benefit.
            </Paragraph>
            <Paragraph>
                The second professor was named Gert Cawenbergs. I did well in his class and we got along. He was
                computational and theoretical, so I could do work from home. But again, I never added to his research
                initiative. Nothing came out of me being in the lab. So that didn’t work out.
            </Paragraph>
            <Paragraph>
                I was friends with a man named Bayle. He was my best friend during graduate school, is the person who most
                recently employed me, and is the only contact from all of the years of my undergraduate education and all of
                the years of graduate school that I am still in touch with. He is a particularly accommodating to mental
                health problems. He worked in the lab of an important professor named Chuck Stevens. Chuck wasn’t accepting
                any students because he plan to retire, but I sort of begged him to let me in because I was desperate. The
                other two rotations went nowhere. I did a rotation with Chuck, on the way, Chuck’s lab worked, everyone had
                their own projects. So there was really no notion of me succeeding or not succeeding. But my work would be a
                series of disconnected projects that went nowhere. I rarely met with him. But he wasn’t really the kind of
                person who was looking out for me. I was assigned to him from the school. It cost him no money to have me in
                his lab. So I was kind of just there, doing my own thing. The only person who really understood what I was
                thinking about it. Any given time was Bayle.
            </Paragraph>
            <Paragraph>
                In graduate school I continue dating Kasia for sometime. I’m not sure what we were holding onto exactly
                because she still stayed at Uchicago to finish school. I would’ve stayed there too, but we were struggling.
                She visited me one time, and we got into a fight that led to a physical creation. The cops were called and I
                was arrested. No one saw the fight, they just heard the yelling. I spent the night in jail, but I’m pretty
                sure I was the one who told the cops what I did. Kasia bailed me out. We both contributed to the escalation
                and she was sorry for her part, but we realized it was time to break up. I was lost after that.
            </Paragraph>
            <Paragraph>
                I dated another woman named Pauline. This was around the time where I was trying to complete my master’s
                thesis. I really struggled with it. I assembled a committee which you had to do, and the first draft I
                wrote, the committee decided that they could not evaluate. It was extremely technical and I was making up my
                own math. That’s not to say it wasn’t valid, but I literally had a committee that just said they were not
                qualified to assess the merit of my work. In an act of kindness I suppose, they gave me very specific
                guidelines on what to write instead. The problem was that I was working in this purely theoretical context.
                Didn’t have laboratory results. When I was undergrad, I worked in lab with data. Wrote up the version of my
                thesis that the committee asked me to, and they let me pass. I was extremely manic at this time. Getting
                that paper done was a fight for survival.
            </Paragraph>
            <Paragraph>
                Friendswood come and go in my life. That’s what mania is like. I remember another time where I was working
                on a paper for a class. I guess partially because I had no grounding to my research, this became very
                important to me. I actually took an incomplete grade to get it done. I invented novel mathematics for this
                thing, and it was part of a very interesting experimental investigation of chaotic systems. The professor
                gave me an A in the class despite me taking an incomplete on my own. It is obviously strange to do something
                like that. It was a sign of just how much my life lacked purpose. I really don’t remember where my parents
                were and all of this. It was a manic haze
            </Paragraph>
        </Message>
