        <Message
            at="2024-11-02T06:16:30.454093Z"
        >
            <Origin>ca60e87c-bd9c-4023-b9a9-b8f1885bb629</Origin>
            <Speaker>$[[ Doug ]]( Dougs Story )</Speaker>
            <Paragraph>
                The school didn’t know about the domestic violence incident. I don’t know how that ended up being reported,
                but I had to see a psychologist. He was a man. I don’t remember his name, but I had to talk about the
                incident. It was incredibly hard for me to acknowledge that I had a woman. I remember him being
                understanding and that being very important. I would have been approximately 25 at that time. It would not
                be until I was 39 that I told another person what had happened
            </Paragraph>
            <Paragraph>
                My mania worsened, my sleep disturbance was it an all-time high in terms of dysregulation. I knew that I
                needed to leave. I knew it wasn’t working. I was seeing a psychiatrist, but I don’t remember her name and I
                don’t even think I can look her up. She was medicating me for ADHD and depression. ADHD was the wrong
                diagnosis and the Adderall that she prescribed me did not help. It made things much worse.
            </Paragraph>
            <Paragraph>
                You can tell from the way I process this just how manic I was. I wanted to finish my graduate school
                research, so I started working with the data that I used to work with when I was an undergrad. I visited
                Chicago somewhere along the way and spoke to my old undergraduate professor about my research. I think he
                thought it was interesting, but we didn’t have any agreement or anything
            </Paragraph>
            <Paragraph>
                I was mugged and beaten up pretty badly somewhere in here. That might have triggered the intensity of this
                decision along with the stimulants. I don’t even know what I told the school, but I decided that I was going
                to move to Chicago to finish my PD work there. I did not think to Nicho this, the person I would be working
                with
            </Paragraph>
            <Paragraph>
                I had a friend in Chicago who I was close with. I suppose he was the reason I wanted to go there too - he
                worked in the same lab. Do you know what my plan was. I’m not sure why he told not to talk to Nicho first. I
                have no clue what my parents said about this decision. Maybe everyone just assumed that I was doing
                something more rational than I was, or maybe everyone was expressing extreme concern, and I was ignoring it.
                But I packed up all of my stuff from San Diego and drove to Chicago, living on my friend Kevin’s couch well
                I looked for an apartment, planning to continue going to my graduate school in San Diego while working in
                Chicago. This is not a normal way of doing things, but I had so little oversight or accountability that I
                could literally move across the country and no one would stop paying me my research stipend…
            </Paragraph>
            <Paragraph>
                The first day I showed up to Nicho’s lab and told him of my plan to work there was a very dark day for me.
                He was confused and did not know what to do with me.. I remember seeing the expression of confusion on his
                face, and it served as a mirror into just how sick I was. I remember being in Kevin’s basement, having a
                panic attack because I was in Chicago with no reason to be there, having moved all my things believing in
                this fantasy. I checked myself into a hospital.
            </Paragraph>
        </Message>
