        <Message
            at="2024-11-02T06:38:21.649990Z"
        >
            <Origin>d80a5710-67ea-4b80-8f5d-9c830e11709a</Origin>
            <Speaker>$[[ Doug ]]( Dougs Story )</Speaker>
            <Paragraph>
                What happens next is strange, and the testament to be being lovable despite all of this, and a testament to
                me really not understanding how serious my condition was - nor anyone else in my life
            </Paragraph>
            <Paragraph>
                I had met a woman named Laura at a wedding when I was in San Diego. The wedding was even on Long Island, but
                she lived there. And when I got there, I looked her up. She was a very nurturing person. She was a nurse,
                and she had her own apartment, and we started dating. I wasn’t getting along with my mother, who absolutely
                couldn’t stand my cat, so Laura took my cat for me
            </Paragraph>
            <Paragraph>
                I started spending more and more time at Laura‘s apartment. I didn’t have a job. so when she was at work, I
                would be there in her apartment alone. But her doing well inspired me to do well. This probably could have
                or should have been a time where I rested and healed myself, before going back to San Diego to finish grad
                school. But I was too terrified and embarrassed to imagine doing that. So I took a leave of absence and
                never returned
            </Paragraph>
            <Paragraph>
                I then decided to get a job. While my graduate education was nuts, finishing my dissertation for the
                classwork part of my education earned me a masters degree. So it was easy enough to say that I went to
                school and got a masters degree. It turns out you need to fill out some form to get that masters degree. It
                would turn up in a background check at a job that I didn’t have the master degree. I said I did. Now, it was
                a relatively simple fix. But it indicates the degree to which I did not really know what was going on
            </Paragraph>
            <Paragraph>
                I had a friend name Mike from high school and he was a software engineer. I had computer programming skills
                from my time as a scientist, so he made an internship at his company for me. I was paid $20 an hour to learn
                how to develop software for him full-time. I didn’t have any responsibilities other than to learn.
            </Paragraph>
            <Paragraph>
                I guess I thought this internship was beneath me. I was in a comfortable place with a friend. Maybe it was
                hard-working for him because he was sort of like my boss. I somehow managed to get a job at a very high
                profile hedge fund. They were the ones that did that background check. I left that internship after they
                offered me a job, which was a rude thing to do. They paid me entirely to learn this thing, and then I left
                once I learned it.
            </Paragraph>
            <Paragraph>
                I moved from New York to Connecticut to work at that hedge fund , which is one of the biggest hedge funds in
                the world - Bridgewater. I don’t know what I was thinking. I didn’t know anything about finance, or finance
                culture. That job simply did not work out for me. I believe I left after six weeks. While there was a job
                this time, I still picked up and left and moved to Connecticut. Something I should not have been doing in my
                state of instability.
            </Paragraph>
            <Paragraph>
                Laura and I had agreed that if it worked out there she would move to come see me. It didn’t work out, so I
                moved in with her, more officially this time. She was renting her apartment from the family, and they caught
                on that we were both living there, decided to raise the rent, and we decided to go a different place because
                we could do better for the money.
            </Paragraph>
            <Paragraph>
                I tried to get that job again with the company I interned for, but they did not offer it to me. I imagine
                this is because they were not happy that I turned it down in the first place. That was a poor choice. I
                remember being really angry, but in retrospect, it was just another mirror to show me how bad my
                decision-making process was
            </Paragraph>
        </Message>
