        <Message
            at="2024-11-02T06:51:50.114383Z"
        >
            <Origin>516adaf0-3d85-4558-963e-37161f1b0de0</Origin>
            <Speaker>$[[ Doug ]]( Dougs Story )</Speaker>
            <Paragraph>
                I’m not sure I would say I was dependent on others for stability in the sense that there was no time of
                unemployment. And I was paid really well for my six weeks at the hedge fund. They give good salaries. I had
                to rush, but I found a job really quickly after that, but I absolutely hated working at. It was a humbling
                experience.
            </Paragraph>
            <Paragraph>
                The saving grace at that company was that I brought my cousin Chris to work with me. I worked hard to learn
                how to be a competent software engineer, reading and studying on my own. I quickly became one of the
                software engineers there. My cousin Chris needed a job and so this time I got him an internship. I
                definitely needed him there to get by
            </Paragraph>
            <Paragraph>
                There were times when I would get really angry with him to the point that it caused problems between me and
                his family . He forgave me. I don’t remember anything that happened. I think I was projecting my fear and
                instability onto him. He and I have talked about it since, and he forgave me - without me having to ask. I
                wouldn’t realize how badly I treated him until years later when a common coworker pointed out that it was
                triggering him. This would be after my next hospitalization and being on medication. I apologize to Chris
                and he just said “I’m still here, aren’t I”. Which is probably the greatest expression of brotherly love one
                could possibly imagine.
            </Paragraph>
            <Paragraph>
                I wasn’t happy at that company, Valiant, So I decided to leave. Not a great move, because I had Chris there.
                I guess I was depended on people for stability, and didn’t realize it. I shouldn’t have left Mike and Laura
                to work in Connecticut. I shouldn’t have left Chris. But I could not live with myself working at this
                company
            </Paragraph>
            <Paragraph>
                When I left Valiant, my boss was unhappy with me to the point of not being willing to give me a referral
            </Paragraph>
            <Paragraph>
                I got a job at this small start up doing basic software engineering. It was called IR2020. I did find there
                for a little while, but I remember a few episodes. I think I had a panic attack and it probably involved
                fighting with one of my bosses. Erick crying sitting on the floor in a room alone at work. I think I left
                the company shortly after. I don’t remember the details but whatever happened, again I couldn’t get a get a
                referral from my boss
            </Paragraph>
            <Paragraph>
                I left that company after about a year, which seems to be an amount of time in both jobs and relationships
                for me where things fall off the wagon
            </Paragraph>
            <Paragraph>
                Laura was a godsend. For whatever reason she loved me no matter what. She and I did not have a relationship
                that was punctuated with fighting and codependency. I guess she was special. I mean, I would end up marrying
                her.
            </Paragraph>
        </Message>
