        <Message
            at="2024-11-02T07:01:57.938386Z"
        >
            <Origin>99deb782-7330-49f5-ba03-438628ceb2c2</Origin>
            <Speaker>$[[ Doug ]]( Dougs Story )</Speaker>
            <Paragraph>
                I got another job at a start up. This one started in New York City, but quickly went remote. The remote work
                was not good for me. I started having trouble with my sleep patterns, I started having trouble showing up to
                work. Again, I made it to the shop for about a year. Everything is hazy. I genuinely cannot remember the
                details of this point in my life, because I wasn’t speaking to anyone about it. I was seeing that nurse
                practitioner that my mother helped me find. She was not providing adequate care. I would be surprised if she
                spoke to the hospital I stayed at. I don’t recall having a diagnosis. I think she was treating me for
                anxiety and depression. During this time I had a falling out, at which point I lost access to my medication.
                Anxiety and panic is another feature of my illness. It was usually moments of panic that I would leave jobs.
                In retrospect, it would happen at times when my illness became apparent and I would get reprimanded for
                doing a bad job or something. I was not raised to think it was OK to do a bad job at something, I’m sure my
                ego was fragile from all these failures
            </Paragraph>
            <Paragraph>
                This was called powerinbox, and something happened with my boss. I think maybe he was upset because I was
                not showing up to morning meetings on time because I was having trouble sleeping. I know that this was
                around the same time. I stopped talking to my therapist because we got into a disagreement over something.
                Those two things are probably related
            </Paragraph>
            <Paragraph>
                I was becoming severely manic. I was doing remote work for a team that was mostly based in Israel, so there
                was very little oversight to my job. And I deteriorated. Without the anti-anxiety meds, and without the
                structure, I just lost my grip. I quit that job without another option, And decided to try whatever for a
                while - freelancing? I didn’t succeed at anything, I just became manic. Ironically it was a very passionate
                time for Laura and I. There was something about my mania, that she found lovable
            </Paragraph>
            <Paragraph>
                But that man grew out of control, and grew bad. I started becoming delusional. Not working and being manic
                caught up with me at some point, and I saw myself in disarray, had an intense panic attack, and checked
                myself into the hospital
            </Paragraph>
        </Message>
