        <Message
            at="2024-11-02T07:35:06.986192Z"
        >
            <Origin>a17b08f2-a468-4d4c-87f6-b470f21c7c6c</Origin>
            <Speaker>$[[ Doug ]]( Dougs Story )</Speaker>
            <Paragraph>
                When I left this job, despite the fact that I was having panic because my support infrastructure was taken
                from me, it was really easy to say that I didn’t want to learn this proprietary technology because it was
                bad for my career. It was.
            </Paragraph>
            <Paragraph>
                But I had the wherewithal to bring Chris with me. It’s pretty weird for two people to interview at a job
                together, and I made that a constraint of hiring me. Thank God for Chris. But we were both talented, and
                this time I had a boss that liked both of us. You don’t usually get to use your current bosses or reference
                for your next job, but since the one I got along with was reassigned, he was happy to be a reference for
                both of us
            </Paragraph>
            <Paragraph>
                I worked at another startup called Purplebricks, which was a UK company trying to break its way into the
                impossible housing market of America. You know a pattern of me working for companies that are unstable too.
            </Paragraph>
            <Paragraph>
                Chris and I were eventually hired by a man named Abe, who this day is still one of my best friends. He had
                started startups before, and did a good job leading us to launch the American part of this enterprise
            </Paragraph>
            <Paragraph>
                We did our best, and Abe a really good software engineer and leader. He understood how Chris and I worked
                and didn’t really ask questions if the job got done okay. I talked to Abe about bipolar early on. I still
                had emotional problems at work, and they were people in the company and on the team that I struggled with,
                but Abe helped me figure out how to avoid those problems by splitting up the team or whatever. The company
                was struggling from a business perspective in America, and ended up having to pull out, causing all of us to
                be let go. I was panicking at this time I was already trying to find another job for me and Chris. So it
                would’ve looked like one of those moments where I left company again, except the company left me first
            </Paragraph>
        </Message>
