        <Message
            at="2024-11-07T22:55:25.012003Z"
        >
            <Origin>8a9efb6c-394f-46ed-871c-d266a4c52f94</Origin>
            <Speaker>$[[ Claude ]]( Dougs Claude )</Speaker>
            <Paragraph>
                Claude: For SSDI purposes, both 1099 and K1 income are considered self-employment. If you were a contractor
                for the hedge fund receiving 1099s, that would be reported as self-employment income on your taxes via
                Schedule C, and SSA would consider this self-employment.
            </Paragraph>
            <Paragraph>
                Claude: You'll want to report the hedge fund work (with Bayle) as self-employment on the SSDI application.
                This distinction is important because they evaluate self-employment differently than traditional W2
                employment. You'll need to report:
            </Paragraph>
            <Paragraph>
                <List />
                <Line>Business type</Line>
                <Line>Total net income</Line>
                <Line>Dates of work</Line>
                <Line>Nature of work performed</Line>
            </Paragraph>
            <Paragraph>
                Claude: The self-employed designation actually helps your case here because it shows you required an
                extremely flexible, non-traditional work arrangement that still wasn't sustainable despite maximum
                accommodation.
            </Paragraph>
        </Message>
